from openpyxl import load_workbook
from openpyxl.styles import PatternFill
wb=load_workbook('protein_expression.xlsx')
ws=wb['Task']

def is_yellow(cell):
    fill=cell.fill
    if fill is None or fill.patternType is None:
        return False
    # check start_color
    color=fill.start_color
    if color is None:
        return False
    rgb=color.rgb
    return rgb in ('FFFFFF00','FFFF00','00FFFF00')

# collect yellow cells in range A1:Z60
yellow=[]
for row in ws.iter_rows(min_row=1,max_row=60,min_col=1,max_col=26):
    for cell in row:
        if is_yellow(cell):
            yellow.append(cell.coordinate)

print('yellow count', len(yellow))
print('first 50', yellow[:50])
print('range summary:')
from collections import defaultdict
rows=defaultdict(list)
for coord in yellow:
    # simple parse
    import re
    m=re.match(r"([A-Z]+)(\d+)", coord)
    if m:
        rows[int(m.group(2))].append(m.group(1))
for r in sorted(rows)[:20]:
    cols=rows[r]
    print(r, ''.join(cols[:5]), '...', cols[-5:])
